import React from 'react';
import {
  Checkbox as ArcoCheckbox,
  CheckboxProps as ArcoCheckboxProps,
  CheckboxGroupProps as ArcoCheckboxGroupProps
} from '@arco-design/web-react';
import { connect, mapProps, mapReadPretty } from '@formily/react';
import { PreviewText } from '../PreviewText';

type ComposedCheckbox = React.FC<ArcoCheckboxProps> & {
  Group?: React.FC<ArcoCheckboxGroupProps<string | number>>;
};

export const Checkbox: ComposedCheckbox = connect(ArcoCheckbox, mapProps({ value: 'checked',  }));

const Group = connect(ArcoCheckbox.Group, mapProps({ dataSource: 'options' }),  mapReadPretty(PreviewText.Select, {
  mode: 'tags',
}));

Checkbox.Group = Group;

export default Checkbox;
